    r"\s*(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*"
)

_MULTIPLIERS = ("d", "h", "m", "s")
_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}


def parse_duration(s):
    """Parse a duration string like '1h30m' into a number of seconds.

    Units are d, h, m and s; each may appear at most once and only in that
    order. Each amount is a non-negative integer. Surrounding whitespace is
    allowed. Anything else raises ValueError.
    """
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    match = _PATTERN.fullmatch(s)
    if match is None:
        raise ValueError("invalid duration: %r" % (s,))

    groups = match.groups()
    if all(g is None for g in groups):
        raise ValueError("invalid duration: %r" % (s,))

    total = 0
    for amount, unit in zip(groups, _MULTIPLIERS):
        if amount is not None:
            total += int(amount) * _SECONDS[unit]
    return total
